const rows = $json.results || [];

let question = "";
try {
  question =
    $("When Executed by Another Workflow").first().json.question ||
    $("Build Procurement Query").first().json.question ||
    "";
} catch (e) {
  question = "";
}

const suppliers = rows.map((row) => ({
  supplier_id: row.supplier_id || null,
  supplier_name: row.supplier_name || null,
  connected_labels: row.connected_labels || [],
  connected_entity: row.connected_entity || null,
  relationship: row.relationship || null,
}));

return [
  {
    json: {
      agent: "procurement_specialist",
      status: "data_retrieved",
      question,
      summary: "Procurement specialist retrieved supplier-related entities and relationships.",
      suppliers,
      rawResult: $json,
    },
  },
];

const question = $json.question || "";
const suppliers = $json.suppliers || [];
const rawResult = $json.rawResult || {};

const systemPrompt = `
You are a Procurement Specialist Agent for a supply chain knowledge graph.

Your job:
- Analyze supplier-related graph data.
- Explain procurement relevance clearly.
- Identify key supplier connections.
- Highlight risks or gaps if visible.
- Give practical next actions.

Do not invent data. Only use the provided supplier data.
If the data is limited, clearly say that.
Return ONLY valid JSON.
`;

const userPrompt = `
User question:
${question}

Supplier data:
${JSON.stringify(suppliers, null, 2)}

Raw query result:
${JSON.stringify(rawResult, null, 2)}

Return JSON with this exact schema:
{
  "answer": "string",
  "keyFindings": ["string"],
  "supplierInsights": [
    {
      "supplier_id": "string",
      "supplier_name": "string",
      "insight": "string"
    }
  ],
  "recommendations": ["string"],
  "confidence": "low | medium | high"
}
`;

return [
  {
    json: {
      agent: "procurement_specialist",
      question,
      suppliers,
      llmPayload: {
        model: "google/gemma-4-31B-it",
        messages: [
          {
            role: "system",
            content: systemPrompt,
          },
          {
            role: "user",
            content: userPrompt,
          },
        ],
        temperature: 0.2,
        max_tokens: 2048,
      },
    },
  },
];

let outputStr = "";

if ($json.choices?.[0]?.message?.content) {
  outputStr = $json.choices[0].message.content;
} else if ($json.text) {
  outputStr = $json.text;
} else if ($json.response) {
  outputStr = $json.response;
} else {
  outputStr = JSON.stringify($json);
}

// Remove thinking tags and markdown fences if model adds them
outputStr = outputStr
  .replace(/<think>[\s\S]*?<\/think>/gi, "")
  .replace(/^\s*```json/i, "")
  .replace(/^\s*```/i, "")
  .replace(/```\s*$/i, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(outputStr);
} catch (e) {
  parsed = {
    answer: outputStr || "The procurement specialist could not generate a summary.",
    keyFindings: [],
    supplierInsights: [],
    recommendations: [],
    confidence: "low",
  };
}

let question = "";
let suppliers = [];

try {
  question = $("Build LLM Summary Payload").first().json.question || "";
  suppliers = $("Build LLM Summary Payload").first().json.suppliers || [];
} catch (e) {}

return [
  {
    json: {
      agent: "procurement_specialist",
      status: "completed",
      question,
      answer: parsed.answer || "",
      keyFindings: parsed.keyFindings || [],
      supplierInsights: parsed.supplierInsights || [],
      recommendations: parsed.recommendations || [],
      confidence: parsed.confidence || "medium",
      evidence: {
        suppliers,
      },
      rawLlmOutput: parsed,
    },
  },
];

const selectedAgents = $json.selectedAgents || [];

const shouldRun =
  selectedAgents.includes("procurement_specialist") ||
  selectedAgents.includes("all");

return [
  {
    json: {
      ...$json,
      shouldRun,
    },
  },
];

return [
  {
    json: {
      agent: "procurement_specialist",
      domain: "Procurement Specialist",
      status: "skipped",
      question: $json.question || "",
      answer: "",
      keyFindings: [],
      recommendations: [],
      confidence: "not_applicable",
      evidence: {},
    },
  },
];
